import{_ as e,o as a,c as o,a2 as n}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"Comment","description":"","frontmatter":{},"headers":[],"relativePath":"components/comment.md","filePath":"components/comment.md"}'),d={name:"components/comment.md"};function i(r,t,s,h,m,c){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="comment" tabindex="-1">Comment <a class="header-anchor" href="#comment" aria-label="Permalink to &quot;Comment&quot;">​</a></h1><p>Comment is one message of a conversation: who wrote it, when, and what.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for messages left on a document, stacked in a column or as the replies of a <a href="./thread">Thread</a>. The application passes the name, the initials of the person&#39;s <a href="./avatar">Avatar</a> and the time as it words them; <code>edited</code> adds a note such as &quot;(edited)&quot; after the time. Actions on the message, such as a menu, go in <code>actions</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>required</td><td>The name of the person who wrote it</td></tr><tr><td><code>initial</code></td><td>required</td><td>The initials in the person&#39;s Avatar</td></tr><tr><td><code>time</code></td><td></td><td>When it was written</td></tr><tr><td><code>edited</code></td><td></td><td>A note after the time</td></tr><tr><td><code>color</code></td><td></td><td>The person&#39;s color on their Avatar, a CSS color</td></tr><tr><td><code>actions</code></td><td></td><td>The actions on the right of the name (a snippet)</td></tr><tr><td><code>children</code></td><td>required</td><td>The body</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The head is a list item that is not pressed: at least as tall as the list&#39;s items, its height comes from its content, with pad-md above and below, and the name and the time are trimmed to their ink. The small Avatar sits in the first column, in a seat centred on the ink of the first line; the first line holds the name (one line with an ellipsis) and the actions at the right end, and is as tall as the taller of them; the second line holds the time (caption). The name and the time never share a line, so neither is cut in a narrow column. The body follows below, in the name&#39;s column, as text, with pad-md below; that padding is the comment&#39;s edge, so the last line of the body is trimmed there. Its padding above and below is the distance to the edge, so it sits in a container without padding, as a list item does, with pad-md at the sides. The distance between comments belongs to the Stack or the Thread around them.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/comment/" title="Comment" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/comment/" target="_blank" rel="noopener">Comment</a></figcaption></figure>',10)])])}const f=e(d,[["render",i]]);export{p as __pageData,f as default};
